/bin/sh -lc "cat > plan.json << 'EOF'
{\"title\": \"Sunrise Shiksha - Q1 2025-26 Funder Dashboard\", \"subtitle\": \"Enrolment, Attendance and Learning Assessment Progress\", \"_mode\": \"dashboard\", \"panels\": [{\"id\": \"p1\", \"kind\": \"kpi\", \"title\": \"Q1 Enrolment Achievement\", \"sql\": \"SELECT Achieved, \\\"% Achievement\\\" FROM funder_report_q1 WHERE Indicator = 'Students enrolled' LIMIT 1\", \"unit\": \"%\"}, {\"id\": \"p2\", \"kind\": \"bar\", \"title\": \"Enrolment by Class\", \"sql\": \"SELECT class, COUNT(*) AS cnt FROM students_2025_26_enrolment GROUP BY class ORDER BY cnt DESC LIMIT 12\", \"x\": \"class\", \"y\": [\"cnt\"]}, {\"id\": \"p3\", \"kind\": \"line\", \"title\": \"Attendance Trend (Apr-Sep 2025)\", \"sql\": \"WITH avg_attend AS (SELECT class, (COALESCE(\\\"Apr-25\\\", 0) + COALESCE(\\\"May-25\\\", 0) + COALESCE(\\\"Jun-25\\\", 0) + COALESCE(\\\"Jul-25\\\", 0) + COALESCE(\\\"Aug-25\\\", 0) + COALESCE(\\\"Sep-25\\\", 0)) / 6.0 AS avg_attendance FROM students_2025_26_attendance GROUP BY class) SELECT class, avg_attendance FROM avg_attend ORDER BY avg_attendance DESC LIMIT 14\", \"x\": \"class\", \"y\": [\"avg_attendance\"]}, {\"id\": \"p4\", \"kind\": \"kpi\", \"title\": \"Learning Progress\", \"sql\": \"SELECT ROUND(AVG(endline_math - baseline_math), 1) AS avg_gain, COUNT(*) AS students FROM (SELECT b.\\\"Student Name\\\", b.\\\"Math Score (/20)\\\" as baseline_math, e.\\\"Math Score (/20)\\\" as endline_math FROM students_2025_26_assessment_baseline_assessment_june_2025 b JOIN students_2025_26_assessment_endline_assessment_march_2026 e ON b.\\\"Student Name\\\" = e.\\\"Student Name\\\") AS gains\", \"unit\": \"points\"}]}
EOF"

